<template>
    <ol :class="cx('labelList')" :data-p="dataP" v-bind="ptm('labelList')">
        <li v-for="(val, index) in value" :key="index + '_label'" :class="cx('label')" v-bind="ptm('label')">
            <slot name="icon" :value="val" :class="cx('labelIcon')">
                <component v-if="isComponentIcon(val.icon)" :is="resolveIcon(val.icon)" :class="cx('labelIcon')" :style="{ color: val.color }" v-bind="ptm('labelIcon')" />
                <i v-else-if="val.icon" :class="[val.icon, cx('labelIcon')]" :style="{ color: val.color }" v-bind="ptm('labelIcon')" />
                <span v-else :class="cx('labelMarker')" :style="{ backgroundColor: val.color }" v-bind="ptm('labelMarker')" />
            </slot>
            <span :class="cx('labelText')" v-bind="ptm('labelText')">{{ val.label }} ({{ $parentInstance.percentValue(val.value) }})</span>
        </li>
    </ol>
</template>

<script>
import { cn } from '@primeuix/utils';
import { isString } from '@primeuix/utils/object';
import BaseComponent from '@primevue/core/basecomponent';
import { toRaw } from 'vue';

export default {
    name: 'MeterGroupLabel',
    hostName: 'MeterGroup',
    extends: BaseComponent,
    inheritAttrs: false,
    props: {
        value: {
            type: Array,
            default: null
        },
        labelPosition: {
            type: String,
            default: 'end'
        },
        labelOrientation: {
            type: String,
            default: 'horizontal'
        }
    },
    inject: ['$pcMeterGroup'],
    methods: {
        resolveIcon(icon) {
            return isString(icon) ? icon : toRaw(icon);
        },
        isComponentIcon(icon) {
            return !!icon && !isString(icon);
        }
    },
    computed: {
        dataP() {
            return cn({
                [this.$pcMeterGroup.labelOrientation]: this.$pcMeterGroup.labelOrientation
            });
        }
    }
};
</script>
